func testBaseGeneralCommissioningCommand() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    guard let cluster = MTRBaseClusterGeneralCommissioning(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRBaseClusterGeneralCommissioning init")
        return
    }
    cluster.armFailSafe(with: MTRGeneralCommissioningClusterArmFailSafeParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.armFailSafe(with: MTRGeneralCommissioningClusterArmFailSafeParams(), completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.commissioningComplete(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.commissioningComplete(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.commissioningComplete(with: MTRGeneralCommissioningClusterCommissioningCompleteParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.commissioningComplete(with: MTRGeneralCommissioningClusterCommissioningCompleteParams(), completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.setRegulatoryConfigWith(MTRGeneralCommissioningClusterSetRegulatoryConfigParams(), completion: { _, err in mtrExpectInvalidState(err) })
    cluster.setRegulatoryConfigWith(MTRGeneralCommissioningClusterSetRegulatoryConfigParams(), completionHandler: { _, err in mtrExpectInvalidState(err) })
}

